(6148022, 906038, 65234, '<td valign="top">Makes me feel like I need to find an oasis.</td>', 'Makes me feel like I need to find an oasis.', '2010-09-01 08:52:35.000000', NULL, 1),
(6148026, 906178, 65234, '<td valign="top">Tricky exposure!  I like seeing stars, city lights and detail on a moonlit pier all in one scene.  Like I''m in a quiet corner taking a break from the nightlife.</td>', 'Tricky exposure!  I like seeing stars, city lights and detail on a moonlit pier all in one scene.  Like I''m in a quiet corner taking a break from the nightlife.', '2010-09-01 08:54:12.000000', NULL, 1),
(6148028, 905815, 65234, '<td valign="top">Gorgeous scenery!  Intrepid hiker; that can''t be an easy walk without a flat spot in sight.</td>', 'Gorgeous scenery!  Intrepid hiker; that can''t be an easy walk without a flat spot in sight.', '2010-09-01 08:54:55.000000', NULL, 1),
(6148033, 906721, 65234, '<td valign="top">Interesting effect.  I might play with burning on the head a bit more to bring out those details, although as it is it kind of looks like he''s flying into a supernatural ether and will vanish completely into it momentarily.</td>', 'Interesting effect.  I might play with burning on the head a bit more to bring out those details, although as it is it kind of looks like he''s flying into a supernatural ether and will vanish completely into it momentarily.', '2010-09-01 08:57:23.000000', NULL, 1),
(6148037, 904668, 65234, '<td valign="top">Love the reflection in the still pool.</td>', 'Love the reflection in the still pool.', '2010-09-01 08:59:29.000000', NULL, 1),
(6148045, 906507, 65234, '<td valign="top">Lots of nice patterns in the clouds.  Horizon looks a bit askew and the temple looks a bit softer than I expect in a silhouette.  I might play with a contrast boost, too.</td>', 'Lots of nice patterns in the clouds.  Horizon looks a bit askew and the temple looks a bit softer than I expect in a silhouette.  I might play with a contrast boost, too.', '2010-09-01 09:02:35.000000', NULL, 1),
(6148057, 905215, 65234, '<td valign="top">I''m a sucker for Morning Glories and punny titles :-)  Lovely bokeh and I really like the shallow DOF for the most part.  That one mostly OOF leaf smack in the middle is kind of bugging me.  I suspect I would have carefully removed it from the scene or tucked it under the bloom and re-shot ;-)</td>', 'I''m a sucker for Morning Glories and punny titles :-)  Lovely bokeh and I really like the shallow DOF for the most part.  That one mostly OOF leaf smack in the middle is kind of bugging me.  I suspect I would have carefully removed it from the scene or tucked it under the bloom and re-shot ;-)', '2010-09-01 09:07:20.000000', NULL, 1),
(6148059, 902414, 65234, '<td valign="top">I know you can train dogs to wait for a cue before eating a treat, but a frog?!  And how do you train a fly?  OK, maybe the fly is a toy, but it sure looks real to me.  I''m very impressed with this setup :-)</td>', 'I know you can train dogs to wait for a cue before eating a treat, but a frog?!  And how do you train a fly?  OK, maybe the fly is a toy, but it sure looks real to me.  I''m very impressed with this setup :-)', '2010-09-01 09:09:11.000000', NULL, 1),
(6148068, 906837, 65234, '<td valign="top">How adorable!  I don''t see why anyone ever thought baby swans were ugly.</td>', 'How adorable!  I don''t see why anyone ever thought baby swans were ugly.', '2010-09-01 09:11:21.000000', NULL, 1),
