(6150839, 905636, 120058, '<td valign="top">Ohh! I''ve got the same shorts! <br/> <br/>Nice portrait, like the dof and the desat. Nice! 7</td>', 'Ohh! I''ve got the same shorts!  Nice portrait, like the dof and the desat. Nice! 7', '2010-09-03 11:02:30.000000', NULL, 1),
(6150845, 906832, 120058, '<td valign="top">Love the colours but it feels a bit out of focus, too close and just a bit woooahhh!! It would look much better without the reflection from the flash, maybe try to reflect the flash onto something next time, instead of pointing it directly on the object! Other than that, cool picture!</td>', 'Love the colours but it feels a bit out of focus, too close and just a bit woooahhh!! It would look much better without the reflection from the flash, maybe try to reflect the flash onto something next time, instead of pointing it directly on the object! Other than that, cool picture!', '2010-09-03 11:08:15.000000', NULL, 1),
(6150848, 905537, 120058, '<td valign="top">Really nice pic! Love how the wave catches your eyes! 8</td>', 'Really nice pic! Love how the wave catches your eyes! 8', '2010-09-03 11:14:17.000000', NULL, 1),
(6150853, 905057, 120058, '<td valign="top">Lovely! 9!</td>', 'Lovely! 9!', '2010-09-03 11:30:49.000000', NULL, 1),
(6150854, 906866, 120058, '<td valign="top">It''s a cool photo, but it looks a bit overexposed. Her hair is blending in with the sky, details on the wall have disappeared etc. B/W with a detail in colour doesn''t do it for me either. 3</td>', 'It''s a cool photo, but it looks a bit overexposed. Her hair is blending in with the sky, details on the wall have disappeared etc. B/W with a detail in colour doesn''t do it for me either. 3', '2010-09-03 11:33:59.000000', NULL, 1),
(6150855, 906572, 120058, '<td valign="top">It''s hard to see what it is, and it gives me a headache. The blur is just too much. 1</td>', 'It''s hard to see what it is, and it gives me a headache. The blur is just too much. 1', '2010-09-03 11:38:39.000000', NULL, 1),
(6150856, 905101, 56828, '<td valign="top">Looks way to over processed.  The eyes just look freaky.</td>', 'Looks way to over processed.  The eyes just look freaky.', '2010-09-03 11:39:00.000000', NULL, 1),
(6150857, 904283, 120058, '<td valign="top">Haha! Really cool! Lovely colours and the dof makes it perfect! 9</td>', 'Haha! Really cool! Lovely colours and the dof makes it perfect! 9', '2010-09-03 11:39:22.000000', NULL, 1),
(6150858, 906638, 120058, '<td valign="top">A bit too dark for my taste, but a nice picture anyway! 6</td>', 'A bit too dark for my taste, but a nice picture anyway! 6', '2010-09-03 11:40:08.000000', NULL, 1),
(6150865, 906380, 120058, '<td valign="top">Lovely picture! Love the colours and the touch of pink in the clouds! 9!</td>', 'Lovely picture! Love the colours and the touch of pink in the clouds! 9!', '2010-09-03 11:47:54.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(6150866, 906602, 120058, '<td valign="top">Really scared of spiders, but this is really cool! Nice dof and angle. 7!</td>', 'Really scared of spiders, but this is really cool! Nice dof and angle. 7!', '2010-09-03 11:48:27.000000', NULL, 1),
(6150867, 906070, 120058, '<td valign="top">Lovely colours! 7</td>', 'Lovely colours! 7', '2010-09-03 11:48:32.000000', NULL, 1),
(6150888, 906695, 17507, '<td valign="top">I love how there are so few parallel lines even with all the repeating elements.</td>', 'I love how there are so few parallel lines even with all the repeating elements.', '2010-09-03 12:17:47.000000', NULL, 1),
(6150892, 905698, 17507, '<td valign="top">Stark. Haunting.</td>', 'Stark. Haunting.', '2010-09-03 12:20:07.000000', NULL, 1),
(6150893, 905645, 17507, '<td valign="top">This building is so overphotographed that you really have to take it to the next level to have significant impact, and despite being well exposed with pleasant tones, this is too much of a traditional angle and composition, with a flat sky to boot, to impress me much. (6)</td>', 'This building is so overphotographed that you really have to take it to the next level to have significant impact, and despite being well exposed with pleasant tones, this is too much of a traditional angle and composition, with a flat sky to boot, to impress me much. (6)', '2010-09-03 12:21:16.000000', NULL, 1),
(6150894, 906564, 17507, '<td valign="top">There''s a blue cast to this photo that is really unfortunate.</td>', 'There''s a blue cast to this photo that is really unfortunate.', '2010-09-03 12:21:39.000000', NULL, 1),
(6150896, 901401, 17507, '<td valign="top">Cool photo, nice posed, technically strong, a bit too tone mapping going on.</td>', 'Cool photo, nice posed, technically strong, a bit too tone mapping going on.', '2010-09-03 12:22:21.000000', NULL, 1),
