(6151045, 905642, 96751, '<td valign="top">Terrific macro.</td>', 'Terrific macro.', '2010-09-03 14:52:29.000000', NULL, 1),
(6151046, 903591, 96751, '<td valign="top">Wonderful.  The warping is both wonderful and bothersome.  Fabulous detail and tones.</td>', 'Wonderful.  The warping is both wonderful and bothersome.  Fabulous detail and tones.', '2010-09-03 14:53:17.000000', NULL, 1),
