(6151062, 902372, 20168, '<td valign="top">nice variation in poses/attitude in these four puffins</td>', 'nice variation in poses/attitude in these four puffins', '2010-09-03 15:03:59.000000', NULL, 1),
(6151063, 902167, 20168, '<td valign="top">great choice for B/W</td>', 'great choice for B/W', '2010-09-03 15:04:30.000000', NULL, 1),
(6151066, 906380, 96751, '<td valign="top">I usually really like the warping effect of fisheye, but here it''s just a bit too deforming to my eye.</td>', 'I usually really like the warping effect of fisheye, but here it''s just a bit too deforming to my eye.', '2010-09-03 15:07:48.000000', NULL, 1),
(6151067, 906548, 96751, '<td valign="top">So artistic and wonderful.</td>', 'So artistic and wonderful.', '2010-09-03 15:08:06.000000', NULL, 1),
(6151068, 904725, 20168, '<td valign="top">great light breaking across the face of these mYstic mountains :)</td>', 'great light breaking across the face of these mYstic mountains :)', '2010-09-03 15:08:39.000000', NULL, 1),
(6151069, 906431, 20168, '<td valign="top">Peter Iredale sings on! Lovely B/W of this classic wreck</td>', 'Peter Iredale sings on! Lovely B/W of this classic wreck', '2010-09-03 15:10:36.000000', NULL, 1),
(6151070, 906860, 20168, '<td valign="top">love the lake district! sweet coloring and lighting</td>', 'love the lake district! sweet coloring and lighting', '2010-09-03 15:11:17.000000', NULL, 1),
(6151071, 906849, 20168, '<td valign="top">cool stop action and great composition</td>', 'cool stop action and great composition', '2010-09-03 15:11:46.000000', NULL, 1),
(6151073, 905645, 20168, '<td valign="top">beautiful lighting</td>', 'beautiful lighting', '2010-09-03 15:12:47.000000', NULL, 1),
(6151074, 905091, 20168, '<td valign="top">excellent composition</td>', 'excellent composition', '2010-09-03 15:13:02.000000', NULL, 1),
(6151076, 904668, 20168, '<td valign="top">great composition here</td>', 'great composition here', '2010-09-03 15:13:16.000000', NULL, 1),
(6151079, 906428, 96751, '<td valign="top">Very noir.  Nice.</td>', 'Very noir.  Nice.', '2010-09-03 15:20:24.000000', NULL, 1),
(6151080, 903450, 96751, '<td valign="top">I HEART meerkats!!!!  They are so goofy and adorable.</td>', 'I HEART meerkats!!!!  They are so goofy and adorable.', '2010-09-03 15:20:45.000000', NULL, 1),
(6151082, 906574, 96751, '<td valign="top">There are two very strong elements here: the model (whose makeup is gorgeous but hairdo questionable), and the bridge reflection.  I do not think they go together.  Each element is too strong and fights with the other.</td>', 'There are two very strong elements here: the model (whose makeup is gorgeous but hairdo questionable), and the bridge reflection.  I do not think they go together.  Each element is too strong and fights with the other.', '2010-09-03 15:21:47.000000', NULL, 1),
(6151084, 906039, 96751, '<td valign="top">LOL - the ship looks like it''s listing to the right.</td>', 'LOL - the ship looks like it''s listing to the right.', '2010-09-03 15:22:10.000000', NULL, 1),
(6151085, 906612, 96751, '<td valign="top">Great subject and composition, but I''d play around a bit with contrast to get a richer tonal result.</td>', 'Great subject and composition, but I''d play around a bit with contrast to get a richer tonal result.', '2010-09-03 15:22:44.000000', NULL, 1),
(6151086, 906852, 96751, '<td valign="top">I love the feeling that I''m in a hole, watching these aerialists.</td>', 'I love the feeling that I''m in a hole, watching these aerialists.', '2010-09-03 15:23:18.000000', NULL, 1),
(6151087, 906731, 96751, '<td valign="top">Very interesting pov.</td>', 'Very interesting pov.', '2010-09-03 15:23:39.000000', NULL, 1),
(6151089, 901401, 96751, '<td valign="top">I find that HDR works better on objects than on people.  The face is just too disturbing.  The rest of the image is killer.</td>', 'I find that HDR works better on objects than on people.  The face is just too disturbing.  The rest of the image is killer.', '2010-09-03 15:24:14.000000', NULL, 1),
(6151090, 906570, 96751, '<td valign="top">Nice architectural abstract.</td>', 'Nice architectural abstract.', '2010-09-03 15:26:07.000000', NULL, 1),
(6151091, 905808, 96751, '<td valign="top">Such a photogenic subject.</td>', 'Such a photogenic subject.', '2010-09-03 15:26:23.000000', NULL, 1),
(6151093, 905535, 96751, '<td valign="top">Incredible detail.  How fortunate that the light was coming from under him than over.  I''d want to crop it just a little tighter to give this gorgeous bird a little more prominence in the sky.</td>', 'Incredible detail.  How fortunate that the light was coming from under him than over.  I''d want to crop it just a little tighter to give this gorgeous bird a little more prominence in the sky.', '2010-09-03 15:27:22.000000', NULL, 1),
(6151094, 904696, 96751, '<td valign="top">Very interesting image and processing.</td>', 'Very interesting image and processing.', '2010-09-03 15:27:54.000000', NULL, 1),
(6151097, 905726, 96751, '<td valign="top">A gorgeous abstract.  Great title to help focus the eye.  Would love to know how you created the overlay look...</td>', 'A gorgeous abstract.  Great title to help focus the eye.  Would love to know how you created the overlay look...', '2010-09-03 15:32:07.000000', NULL, 1),
(6151098, 905709, 96751, '<td valign="top">Oh come on now.  How much did you pay him for the pose????  Adorable.</td>', 'Oh come on now.  How much did you pay him for the pose????  Adorable.', '2010-09-03 15:32:39.000000', NULL, 1),
(6151100, 906387, 96751, '<td valign="top">Beautiful clarity and tonal range.  Maybe just a bit too centered.</td>', 'Beautiful clarity and tonal range.  Maybe just a bit too centered.', '2010-09-03 15:33:01.000000', NULL, 1),
(6151102, 906700, 96751, '<td valign="top">From the air?  I like how you managed to polarization distortion created by the window.  Very clear.  The tilt makes me a bit queasy.</td>', 'From the air?  I like how you managed to polarization distortion created by the window.  Very clear.  The tilt makes me a bit queasy.', '2010-09-03 15:33:43.000000', NULL, 1),
(6151103, 906763, 96751, '<td valign="top">Nice dof.  Great in b/w</td>', 'Nice dof.  Great in b/w', '2010-09-03 15:33:57.000000', NULL, 1),
(6151104, 906632, 96751, '<td valign="top">So sweet.  I would like to have seem the manes just a little brighter, maybe a tad more contrast to add some tonal variation - the lighting is just a teensy bit flat for me.</td>', 'So sweet.  I would like to have seem the manes just a little brighter, maybe a tad more contrast to add some tonal variation - the lighting is just a teensy bit flat for me.', '2010-09-03 15:34:48.000000', NULL, 1),
(6151105, 902628, 96751, '<td valign="top">Great candid!</td>', 'Great candid!', '2010-09-03 15:35:23.000000', NULL, 1),
(6151106, 906589, 96751, '<td valign="top">So very Adams!!!  Stunning.  This is a place I''ve always wanted to go - and I''ve never had a close encounter of any kind :-)</td>', 'So very Adams!!!  Stunning.  This is a place I''ve always wanted to go - and I''ve never had a close encounter of any kind :-)', '2010-09-03 15:36:00.000000', NULL, 1),
(6151108, 905999, 96751, '<td valign="top">I really like the pp''ing on this, and the nice tonal range and dof of the bridge.  I''m not crazy about her pose.</td>', 'I really like the pp''ing on this, and the nice tonal range and dof of the bridge.  I''m not crazy about her pose.', '2010-09-03 15:36:48.000000', NULL, 1),
(6151109, 904725, 96751, '<td valign="top">I love those clouds.  Gorgeous.</td>', 'I love those clouds.  Gorgeous.', '2010-09-03 15:37:04.000000', NULL, 1),
(6151110, 906197, 96751, '<td valign="top">These are such gorgeous creatures.  I love how complimentary the colors are.</td>', 'These are such gorgeous creatures.  I love how complimentary the colors are.', '2010-09-03 15:37:28.000000', NULL, 1),
(6151111, 905815, 96751, '<td valign="top">Sensational.  What a great sense of space, and the figure adds such perspective. The wide angle really emphasizes the slant.  Great colors and tonal range, with amazing clarity and detail.  I''d perhaps like a tiny bit more lighting in the area around the figure.</td>', 'Sensational.  What a great sense of space, and the figure adds such perspective. The wide angle really emphasizes the slant.  Great colors and tonal range, with amazing clarity and detail.  I''d perhaps like a tiny bit more lighting in the area around the figure.', '2010-09-03 15:38:44.000000', NULL, 1),
(6151112, 906756, 96751, '<td valign="top">What a funny pose.  Love that blue!</td>', 'What a funny pose.  Love that blue!', '2010-09-03 15:38:58.000000', NULL, 1),
(6151113, 905126, 96751, '<td valign="top">This looks like the same model in another image.  Was she part of a group shooting session?  I really like the sun and the flares, and how they light up the gate and wall.</td>', 'This looks like the same model in another image.  Was she part of a group shooting session?  I really like the sun and the flares, and how they light up the gate and wall.', '2010-09-03 15:40:38.000000', NULL, 1),
(6151114, 906221, 96751, '<td valign="top">Very interesting effect.  Great dof and color.</td>', 'Very interesting effect.  Great dof and color.', '2010-09-03 15:41:01.000000', NULL, 1),
(6151116, 906315, 96751, '<td valign="top">There is such a marvelous quality to this image - the deep tones, the great contrast.  For me, the composition is too centered.  I think the far right panel is unnecessary.  I''m not sure the plant helps this image - it is fighting for my attention, and adding a non-flattering shadow to the bride''s silhouette.  Finally, the bride''s pose is a bit forced, although it does create some nice lines.</td>', 'There is such a marvelous quality to this image - the deep tones, the great contrast.  For me, the composition is too centered.  I think the far right panel is unnecessary.  I''m not sure the plant helps this image - it is fighting for my attention, and adding a non-flattering shadow to the bride''s silhouette.  Finally, the bride''s pose is a bit forced, although it does create some nice lines.', '2010-09-03 15:46:41.000000', NULL, 1),
(6151117, 904487, 96751, '<td valign="top">Marvelous architectural abstract.  Great tones and lines.</td>', 'Marvelous architectural abstract.  Great tones and lines.', '2010-09-03 15:47:13.000000', NULL, 1),
(6151119, 906396, 96751, '<td valign="top">Wow.  Great capture.  This is certainly a man-against-the-elements iconic image.  I don''t know if the waves were that big, but the perspective you have chosen and the placement of the figure certainly create that illusion.</td>', 'Wow.  Great capture.  This is certainly a man-against-the-elements iconic image.  I don''t know if the waves were that big, but the perspective you have chosen and the placement of the figure certainly create that illusion.', '2010-09-03 15:48:57.000000', NULL, 1),
(6151120, 904441, 96751, '<td valign="top">Very funky.  Dig how the wall and his bag match.  Not getting the title.</td>', 'Very funky.  Dig how the wall and his bag match.  Not getting the title.', '2010-09-03 15:49:28.000000', NULL, 1),
(6151125, 906429, 96751, '<td valign="top">Very interesting feel about this feather.  It looks plasticky and metallic.  Love the complementary colors.</td>', 'Very interesting feel about this feather.  It looks plasticky and metallic.  Love the complementary colors.', '2010-09-03 15:52:07.000000', NULL, 1),
(6151126, 906105, 96751, '<td valign="top">What a worried little look...</td>', 'What a worried little look...', '2010-09-03 15:52:23.000000', NULL, 1),
(6151129, 906583, 96751, '<td valign="top">How I love me a good tilt shift.  Fabulous.  Love the golden hour lighting and tones.</td>', 'How I love me a good tilt shift.  Fabulous.  Love the golden hour lighting and tones.', '2010-09-03 15:52:55.000000', NULL, 1),
(6151130, 905698, 96751, '<td valign="top">Very compelling image.   I love the contradictions here, the sparse surroundings, the slightly deteriorated belongings, and yet she is so elegant and beautiful.</td>', 'Very compelling image.   I love the contradictions here, the sparse surroundings, the slightly deteriorated belongings, and yet she is so elegant and beautiful.', '2010-09-03 15:54:06.000000', NULL, 1),
(6151134, 906580, 96751, '<td valign="top">Beautiful.</td>', 'Beautiful.', '2010-09-03 15:58:11.000000', NULL, 1),
(6151135, 905426, 96751, '<td valign="top">The tones here are just incredible.  Very opalescent.  And I like how that tiny sailboat balances the image. Not sure about the tilt.</td>', 'The tones here are just incredible.  Very opalescent.  And I like how that tiny sailboat balances the image. Not sure about the tilt.', '2010-09-03 15:59:55.000000', NULL, 1),
(6151137, 906767, 96751, '<td valign="top">Wonderful lines and terrific processing.  Very special.</td>', 'Wonderful lines and terrific processing.  Very special.', '2010-09-03 16:01:13.000000', NULL, 1),
(6151140, 905101, 96751, '<td valign="top">He looks like a manikin...</td>', 'He looks like a manikin...', '2010-09-03 16:01:43.000000', NULL, 1),
(6151141, 902414, 96751, '<td valign="top">Seriously.  How long did you have to wait for this!!!?</td>', 'Seriously.  How long did you have to wait for this!!!?', '2010-09-03 16:02:23.000000', NULL, 1),
(6151142, 906635, 96751, '<td valign="top">Very artistic.  Great colors.</td>', 'Very artistic.  Great colors.', '2010-09-03 16:02:40.000000', NULL, 1),
(6151145, 905579, 96751, '<td valign="top">Funky image.  Love the high contrast.</td>', 'Funky image.  Love the high contrast.', '2010-09-03 16:03:02.000000', NULL, 1),
(6151147, 904290, 96751, '<td valign="top">This looks like Topaz wet rocks :-)  I''m on the fence about the centered composition.</td>', 'This looks like Topaz wet rocks :-)  I''m on the fence about the centered composition.', '2010-09-03 16:04:08.000000', NULL, 1),
(6151148, 904114, 96751, '<td valign="top">Amazing landscape.  But something is off with the lighting.  It''s all to even, and lends a dullness that doesn''t serve the majesty of the image.  Perhaps some dodging of the lighter areas of the hills to get some sort of dappled effect?</td>', 'Amazing landscape.  But something is off with the lighting.  It''s all to even, and lends a dullness that doesn''t serve the majesty of the image.  Perhaps some dodging of the lighter areas of the hills to get some sort of dappled effect?', '2010-09-03 16:05:34.000000', NULL, 1),
(6151149, 905014, 96751, '<td valign="top">Great use of fisheye.  Strong leading lines.</td>', 'Great use of fisheye.  Strong leading lines.', '2010-09-03 16:06:02.000000', NULL, 1),
(6151151, 904872, 96751, '<td valign="top">Incredibly bizarre.  And terrific.  I think the body and shawl are completely unnecessary, and actually detract from the composition.</td>', 'Incredibly bizarre.  And terrific.  I think the body and shawl are completely unnecessary, and actually detract from the composition.', '2010-09-03 16:06:59.000000', NULL, 1),
(6151152, 906838, 96751, '<td valign="top">I could have sworn I already left a comment for this image.  Just love it, the disembodied feeder and birds.  I''m wondering if you used some sort of masking cloth or board to make such a clean bg.  I love all the different attitudes of the birds, and how they are suspended like jewels in the void.  Fabulous colors and details on so many of them.  Great image.</td>', 'I could have sworn I already left a comment for this image.  Just love it, the disembodied feeder and birds.  I''m wondering if you used some sort of masking cloth or board to make such a clean bg.  I love all the different attitudes of the birds, and how they are suspended like jewels in the void.  Fabulous colors and details on so many of them.  Great image.', '2010-09-03 16:08:32.000000', NULL, 1),
(6151154, 906796, 96751, '<td valign="top">Sensational sky.</td>', 'Sensational sky.', '2010-09-03 16:09:20.000000', NULL, 1),
(6151155, 906000, 96751, '<td valign="top">What an exceptional image.  The look on the sibling''s face is just priceless.</td>', 'What an exceptional image.  The look on the sibling''s face is just priceless.', '2010-09-03 16:09:46.000000', NULL, 1),
(6151156, 905954, 96751, '<td valign="top">I can''t tell if the vintagy sheen is intentional or just a lack of contrast.  Nice symmetry.</td>', 'I can''t tell if the vintagy sheen is intentional or just a lack of contrast.  Nice symmetry.', '2010-09-03 16:10:35.000000', NULL, 1),
