(6151715, 904744, 23484, '<td valign="top">Great shot.  I love the upside down look and perfectly composed.</td>', 'Great shot.  I love the upside down look and perfectly composed.', '2010-09-04 09:03:27.000000', NULL, 1),
(6151716, 906879, 23484, '<td valign="top">Nice long exposure.</td>', 'Nice long exposure.', '2010-09-04 09:03:43.000000', NULL, 1),
