(6153852, 904201, 76335, '<td valign="top">I''m sure I''ll be haunted by this. Most fascinating.</td>', 'I''m sure I''ll be haunted by this. Most fascinating.', '2010-09-06 19:47:28.000000', NULL, 1),
(6153853, 901615, 76335, '<td valign="top">Points for doing this in monochrome. It''s a refreshing change -- not just another bug macro with lots of gory detail. Nicely composed too.</td>', 'Points for doing this in monochrome. It''s a refreshing change -- not just another bug macro with lots of gory detail. Nicely composed too.', '2010-09-06 19:47:30.000000', NULL, 1),
(6153856, 906695, 76335, '<td valign="top">Abstract on one level, and brutally real on another. Very effective no matter how you decide to view it.</td>', 'Abstract on one level, and brutally real on another. Very effective no matter how you decide to view it.', '2010-09-06 19:47:36.000000', NULL, 1),
(6153857, 906707, 76335, '<td valign="top">I love your composition -- all those gritty shapes. Excellent.</td>', 'I love your composition -- all those gritty shapes. Excellent.', '2010-09-06 19:47:37.000000', NULL, 1),
(6153858, 906389, 76335, '<td valign="top">A splendid candid. Wedding receptions are great for candid photography.</td>', 'A splendid candid. Wedding receptions are great for candid photography.', '2010-09-06 19:47:39.000000', NULL, 1),
(6153859, 906679, 76335, '<td valign="top">An incredible portrait. Mysterious yet very revealing. The catch light in the eyes is great.</td>', 'An incredible portrait. Mysterious yet very revealing. The catch light in the eyes is great.', '2010-09-06 19:47:45.000000', NULL, 1),
(6153860, 906564, 76335, '<td valign="top">One of the more interesting floral shots. The lighting and colors are simply mesmerizing.</td>', 'One of the more interesting floral shots. The lighting and colors are simply mesmerizing.', '2010-09-06 19:47:47.000000', NULL, 1),
(6153861, 906721, 76335, '<td valign="top">Technically it''s not perfect, and for that reason, I like it even more. Very raw, very real -- a refreshing change from glamour shots of owls and eagles.</td>', 'Technically it''s not perfect, and for that reason, I like it even more. Very raw, very real -- a refreshing change from glamour shots of owls and eagles.', '2010-09-06 19:47:49.000000', NULL, 1),
(6153862, 905948, 76335, '<td valign="top">So many subtle things to take in here. An excellent and revealing portrait.</td>', 'So many subtle things to take in here. An excellent and revealing portrait.', '2010-09-06 19:47:52.000000', NULL, 1),
(6153863, 906713, 76335, '<td valign="top">Quirky. I like it. Seven.</td>', 'Quirky. I like it. Seven.', '2010-09-06 19:47:54.000000', NULL, 1),
(6153865, 906510, 76335, '<td valign="top">Fabulous perspective. Nice to see something different. I like the effects of the lights and how they seem to be interacting with the performer.</td>', 'Fabulous perspective. Nice to see something different. I like the effects of the lights and how they seem to be interacting with the performer.', '2010-09-06 19:48:12.000000', NULL, 1),
(6153866, 904666, 76335, '<td valign="top">Beautifully composed -- the way the elements are arranged in that sea of green.</td>', 'Beautifully composed -- the way the elements are arranged in that sea of green.', '2010-09-06 19:48:16.000000', NULL, 1),
(6153867, 906750, 76335, '<td valign="top">Beautifully bizarre.</td>', 'Beautifully bizarre.', '2010-09-06 19:48:18.000000', NULL, 1),
