(6153923, 906791, 97225, '<td valign="top">Beautiful shot. The focus/dof is brilliant.</td>', 'Beautiful shot. The focus/dof is brilliant.', '2010-09-06 21:03:46.000000', NULL, 1),
(6153931, 906205, 107338, '<td valign="top">wow. great shot!</td>', 'wow. great shot!', '2010-09-06 21:11:48.000000', NULL, 1),
(6153944, 906409, 97225, '<td valign="top">The sky, the sea, the rocks - all elements are interesting, and have been nicely composed  to make a pleasing image. I like the reflective pools which break up the dark grey foreground and make that area more lively.</td>', 'The sky, the sea, the rocks - all elements are interesting, and have been nicely composed  to make a pleasing image. I like the reflective pools which break up the dark grey foreground and make that area more lively.', '2010-09-06 21:29:38.000000', NULL, 1),
