(6154051, 905019, 62989, '<td valign="top">This is such a fine picture - everything works here - the writing, the plants, the clour on the wall but especually the nonchalant way thbat kid has kicked one shoe off and stood like a catwalk model - from the overall feel of the shot i''m guessing this is from somewhere relatively non wealthy - it is a real change to see kids in far flung places portrayed as kids rather than starvation victims or objects of pity - 10 (aka the kiss of death)</td>', 'This is such a fine picture - everything works here - the writing, the plants, the clour on the wall but especually the nonchalant way thbat kid has kicked one shoe off and stood like a catwalk model - from the overall feel of the shot i''m guessing this is from somewhere relatively non wealthy - it is a real change to see kids in far flung places portrayed as kids rather than starvation victims or objects of pity - 10 (aka the kiss of death)', '2010-09-06 23:06:41.000000', NULL, 1),
(6154097, 906695, 75618, '<td valign="top">This is BEAUTIFUL, I like how the bright cheery colors provide a contrast against all that decay. 9</td>', 'This is BEAUTIFUL, I like how the bright cheery colors provide a contrast against all that decay. 9', '2010-09-07 01:03:32.000000', NULL, 1),
(6154099, 906836, 54944, '<td valign="top">wow, you''re immediately drawn to the eyes...the high key really helps, though it kind of falls off for the bottom half of the image. actually, this might be partially  why you''re really drawn to the eyes..anyway, great portrait.</td>', 'wow, you''re immediately drawn to the eyes...the high key really helps, though it kind of falls off for the bottom half of the image. actually, this might be partially  why you''re really drawn to the eyes..anyway, great portrait.', '2010-09-07 01:08:32.000000', NULL, 1),
(6154100, 906829, 75618, '<td valign="top">The duotone and lighting set the mood in this. I was intrigued and captivated until I realized it was a museum shot, which ruined the otherworldly feel of it in a way. 8</td>', 'The duotone and lighting set the mood in this. I was intrigued and captivated until I realized it was a museum shot, which ruined the otherworldly feel of it in a way. 8', '2010-09-07 01:11:39.000000', NULL, 1),
(6154103, 905726, 54944, '<td valign="top">My mind was just blown.</td>', 'My mind was just blown.', '2010-09-07 01:14:14.000000', NULL, 1),
(6154104, 906141, 75618, '<td valign="top">Very pretty. I love how you left out the imperfections in the leaves. 7</td>', 'Very pretty. I love how you left out the imperfections in the leaves. 7', '2010-09-07 01:14:27.000000', NULL, 1),
(6154106, 904081, 75618, '<td valign="top">Great stuff, it''s like peering into a different almost surreal universe! 8</td>', 'Great stuff, it''s like peering into a different almost surreal universe! 8', '2010-09-07 01:16:51.000000', NULL, 1),
(6154108, 906866, 75618, '<td valign="top">This made me smile. :)  I like the cheesy pose and the partial desat. 8</td>', 'This made me smile. :)  I like the cheesy pose and the partial desat. 8', '2010-09-07 01:20:27.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(6154112, 905816, 75618, '<td valign="top">Haha, very creative! Great tonalities in the ridges. I would have liked this better with the bright portion of the sky cropped off. 7</td>', 'Haha, very creative! Great tonalities in the ridges. I would have liked this better with the bright portion of the sky cropped off. 7', '2010-09-07 01:23:14.000000', NULL, 1),
