(6154126, 905698, 75618, '<td valign="top">A very melancholic environmental portrait. Love the assortment of the things in the picture. One thing that struck me in particular is that the bed is a twin, which implies that she probably lives alone. 8</td>', 'A very melancholic environmental portrait. Love the assortment of the things in the picture. One thing that struck me in particular is that the bed is a twin, which implies that she probably lives alone. 8', '2010-09-07 01:44:33.000000', NULL, 1),
(6154129, 906000, 30982, '<td valign="top">Absolutely delightful.  By far one of my favorites in the challenge.  Definitely one to print for the family!</td>', 'Absolutely delightful.  By far one of my favorites in the challenge.  Definitely one to print for the family!', '2010-09-07 01:49:06.000000', NULL, 1),
(6154130, 906705, 30982, '<td valign="top">Something eerie and disturbing about the foreground smiling gent.  Well done.</td>', 'Something eerie and disturbing about the foreground smiling gent.  Well done.', '2010-09-07 01:49:59.000000', NULL, 1),
